WITH base AS (SELECT id, customer_id, browser, started_at, country, LENGTH(device) AS device_length FROM sessions WHERE started_at >= DATE '2023-05-30'), flagged AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_session FROM base), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT DATE_TRUNC('MONTH', started_at) AS activity_month, country, COUNT(DISTINCT customer_id) AS distinct_customer_ids, MIN(started_at) AS first_seen, GROUPING(DATE_TRUNC('MONTH', started_at)) AS grouping_id FROM sessionized GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', started_at), country), (DATE_TRUNC('MONTH', started_at)), ()) ORDER BY distinct_customer_ids DESC
